head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script 탭에서 var json 부분을 확인한다.
    //1. In the Script tab, check the var json section.
    //Verify  1. ... dataList5.setJSON (json);
    //Test step 2. Source 탭 또는 Property 탭에서 fwGanttChart2 의 ref 부분을 확인한다.
    //2. In the Source or Property tab, check the ref section of fwGanttChart2.
    //Verify 2. ref="data:dataList5"
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('fwGanttChart2').getAttribute('ref')", "data:dataList5");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 브라우저에서 확인한다.
    //3. Check in the browser.
    //Verify 3. 정상적으로 차트가 그려진다. (20170224 버전에서는 차트가 나오지 않음)
    //3. The chart is drawn normally. (Charts do not appear in version 20170224)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('fw_gantt_'+$p.id+'fwGanttChart2').style.display", "inline-block");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
